    internal static uint CommonData(SyntaxNode node)
    {
        switch (node)
        {
            case HeritageClauseNode n: return ((n.Token switch { SyntaxKind.ExtendsKeyword => 0u, SyntaxKind.ImplementsKeyword => 1u, _ => 0u }) << 24);
            case ImportSpecifierNode n: return (n.IsTypeOnly ? 1u << 24 : 0);
            case ExportSpecifierNode n: return (n.IsTypeOnly ? 1u << 24 : 0);
            case JsxTextNode n: return (n.ContainsOnlyTriviaWhiteSpaces ? 1u << 24 : 0);
            case BlockNode n: return (n.MultiLine ? 1u << 24 : 0);
            case ModuleDeclarationNode n: return ((n.Keyword switch { SyntaxKind.ModuleKeyword => 0u, SyntaxKind.NamespaceKeyword => 1u, _ => 0u }) << 24);
            case ExportAssignmentNode n: return (n.IsExportEquals ? 1u << 24 : 0);
            case PrefixUnaryExpressionNode n: return ((n.Operator switch { SyntaxKind.PlusToken => 0u, SyntaxKind.MinusToken => 1u, SyntaxKind.TildeToken => 2u, SyntaxKind.ExclamationToken => 3u, SyntaxKind.PlusPlusToken => 4u, SyntaxKind.MinusMinusToken => 5u, _ => 0u }) << 24);
            case PostfixUnaryExpressionNode n: return ((n.Operator switch { SyntaxKind.PlusPlusToken => 0u, SyntaxKind.MinusMinusToken => 1u, _ => 0u }) << 24);
            case MetaPropertyNode n: return ((n.KeywordToken switch { SyntaxKind.ImportKeyword => 0u, SyntaxKind.NewKeyword => 1u, _ => 0u }) << 24);
            case ArrayLiteralExpressionNode n: return (n.MultiLine ? 1u << 24 : 0);
            case ObjectLiteralExpressionNode n: return (n.MultiLine ? 1u << 24 : 0);
            case TypeOperatorNode n: return ((n.Operator switch { SyntaxKind.KeyOfKeyword => 0u, SyntaxKind.ReadonlyKeyword => 1u, SyntaxKind.UniqueKeyword => 2u, _ => 0u }) << 24);
            case ImportAttributesNode n: return (n.MultiLine ? 1u << 24 : 0) | ((n.Token switch { SyntaxKind.WithKeyword => 0u, SyntaxKind.AssertKeyword => 1u, _ => 0u }) << 25);
            case SyntheticExpressionNode: throw new InvalidDataException("Synthetic expressions cannot be encoded");
            case ImportEqualsDeclarationNode n: return (n.IsTypeOnly ? 1u << 24 : 0);
            case ExportDeclarationNode n: return (n.IsTypeOnly ? 1u << 24 : 0);
            case ImportTypeNode n: return (n.IsTypeOf ? 1u << 24 : 0);
            case ImportClauseNode n: return ((n.PhaseModifier switch { SyntaxKind.TypeKeyword => 1u, SyntaxKind.DeferKeyword => 2u, _ => 0u }) << 24);
            case JSDocTypeLiteralNode n: return (n.IsArrayType ? 1u << 24 : 0);
            case JSDocParameterOrPropertyTagNode n: return (n.IsBracketed ? 1u << 24 : 0) | (n.IsNameFirst ? 1u << 25 : 0);
            default: return 0;
        }
    }

    internal static Utf8String Text(SyntaxNode node)
    {
        switch (node)
        {
            case JsxTextNode n: return n.Text;
            case IdentifierNode n: return n.Text;
            case StringLiteralNode n: return n.Text;
            case NoSubstitutionTemplateLiteralNode n: return n.Text;
            case NumericLiteralNode n: return n.Text;
            case PrivateIdentifierNode n: return n.Text;
            case BigIntLiteralNode n: return n.Text;
            case JSDocTextNode n: return Utf8String.Concat(n.Text);
            case JSDocLinkNode n: return Utf8String.Concat(n.Text);
            case JSDocLinkCodeNode n: return Utf8String.Concat(n.Text);
            case JSDocLinkPlainNode n: return Utf8String.Concat(n.Text);
            case RegularExpressionLiteralNode n: return n.Text;
            case TemplateHeadNode n: return n.Text;
            case TemplateMiddleNode n: return n.Text;
            case TemplateTailNode n: return n.Text;
            default: throw new InvalidDataException("Node has no encoded text");
        }
    }

