    internal static void ReadCommon(SyntaxNode node, uint data)
    {
        switch (node)
        {
            case HeritageClauseNode n:
                n.Token = ((data >> 24) & 1) switch { 0 => SyntaxKind.ExtendsKeyword, 1 => SyntaxKind.ImplementsKeyword, _ => throw new InvalidDataException("Invalid AST common data") };
                break;
            case ImportSpecifierNode n:
                n.IsTypeOnly = (data & (1u << 24)) != 0;
                break;
            case ExportSpecifierNode n:
                n.IsTypeOnly = (data & (1u << 24)) != 0;
                break;
            case JsxTextNode n:
                n.ContainsOnlyTriviaWhiteSpaces = (data & (1u << 24)) != 0;
                break;
            case BlockNode n:
                n.MultiLine = (data & (1u << 24)) != 0;
                break;
            case ModuleDeclarationNode n:
                n.Keyword = ((data >> 24) & 1) switch { 0 => SyntaxKind.ModuleKeyword, 1 => SyntaxKind.NamespaceKeyword, _ => throw new InvalidDataException("Invalid AST common data") };
                break;
            case ExportAssignmentNode n:
                n.IsExportEquals = (data & (1u << 24)) != 0;
                break;
            case PrefixUnaryExpressionNode n:
                n.Operator = ((data >> 24) & 7) switch { 0 => SyntaxKind.PlusToken, 1 => SyntaxKind.MinusToken, 2 => SyntaxKind.TildeToken, 3 => SyntaxKind.ExclamationToken, 4 => SyntaxKind.PlusPlusToken, 5 => SyntaxKind.MinusMinusToken, _ => throw new InvalidDataException("Invalid AST common data") };
                break;
            case PostfixUnaryExpressionNode n:
                n.Operator = ((data >> 24) & 1) switch { 0 => SyntaxKind.PlusPlusToken, 1 => SyntaxKind.MinusMinusToken, _ => throw new InvalidDataException("Invalid AST common data") };
                break;
            case MetaPropertyNode n:
                n.KeywordToken = ((data >> 24) & 1) switch { 0 => SyntaxKind.ImportKeyword, 1 => SyntaxKind.NewKeyword, _ => throw new InvalidDataException("Invalid AST common data") };
                break;
            case ArrayLiteralExpressionNode n:
                n.MultiLine = (data & (1u << 24)) != 0;
                break;
            case ObjectLiteralExpressionNode n:
                n.MultiLine = (data & (1u << 24)) != 0;
                break;
            case TypeOperatorNode n:
                n.Operator = ((data >> 24) & 3) switch { 0 => SyntaxKind.KeyOfKeyword, 1 => SyntaxKind.ReadonlyKeyword, 2 => SyntaxKind.UniqueKeyword, _ => throw new InvalidDataException("Invalid AST common data") };
                break;
            case ImportAttributesNode n:
                n.MultiLine = (data & (1u << 24)) != 0;
                n.Token = ((data >> 25) & 1) switch { 0 => SyntaxKind.WithKeyword, 1 => SyntaxKind.AssertKeyword, _ => throw new InvalidDataException("Invalid AST common data") };
                break;
            case ImportEqualsDeclarationNode n:
                n.IsTypeOnly = (data & (1u << 24)) != 0;
                break;
            case ExportDeclarationNode n:
                n.IsTypeOnly = (data & (1u << 24)) != 0;
                break;
            case ImportTypeNode n:
                n.IsTypeOf = (data & (1u << 24)) != 0;
                break;
            case ImportClauseNode n:
                n.PhaseModifier = ((data >> 24) & 3) switch { 0 => SyntaxKind.Unknown, 1 => SyntaxKind.TypeKeyword, 2 => SyntaxKind.DeferKeyword, _ => throw new InvalidDataException("Invalid AST common data") };
                break;
            case JSDocTypeLiteralNode n:
                n.IsArrayType = (data & (1u << 24)) != 0;
                break;
            case JSDocParameterOrPropertyTagNode n:
                n.IsBracketed = (data & (1u << 24)) != 0;
                n.IsNameFirst = (data & (1u << 25)) != 0;
                break;
        }
    }

    internal static void SetText(SyntaxNode node, Utf8String value)
    {
        switch (node)
        {
            case JsxTextNode n: n.Text = value; break;
            case IdentifierNode n: n.Text = value; break;
            case StringLiteralNode n: n.Text = value; break;
            case NoSubstitutionTemplateLiteralNode n: n.Text = value; break;
            case NumericLiteralNode n: n.Text = value; break;
            case PrivateIdentifierNode n: n.Text = value; break;
            case BigIntLiteralNode n: n.Text = value; break;
            case JSDocTextNode n: n.Text = [value]; break;
            case JSDocLinkNode n: n.Text = [value]; break;
            case JSDocLinkCodeNode n: n.Text = [value]; break;
            case JSDocLinkPlainNode n: n.Text = [value]; break;
            case RegularExpressionLiteralNode n: n.Text = value; break;
            case TemplateHeadNode n: n.Text = value; break;
            case TemplateMiddleNode n: n.Text = value; break;
            case TemplateTailNode n: n.Text = value; break;
            default: throw new InvalidDataException("Node has no encoded text");
        }
    }

    internal static void ReadChildren(SyntaxNode node, uint mask, ref AstChildReader children)
    {
        switch (node)
        {
            case CaseOrDefaultClauseNode n:
                n.Expression = children.Node<SyntaxNode>(mask, 0);
                n.Statements = children.List(mask, 1);
                break;
            case VariableDeclarationNode n:
                n.Name = children.Node<SyntaxNode>(mask, 0);
                n.ExclamationToken = children.Node<SyntaxNode>(mask, 1);
                n.Type = children.Node<SyntaxNode>(mask, 2);
                n.Initializer = children.Node<SyntaxNode>(mask, 3);
                break;
            case BindingElementNode n:
                n.DotDotDotToken = children.Node<SyntaxNode>(mask, 0);
                n.PropertyName = children.Node<SyntaxNode>(mask, 1);
                n.Name = children.Node<SyntaxNode>(mask, 2);
                n.Initializer = children.Node<SyntaxNode>(mask, 3);
                break;
            case TypeParameterDeclarationNode n:
                n.Modifiers = children.List(mask, 0);
                n.Name = children.Node<IdentifierNode>(mask, 1);
                n.Constraint = children.Node<SyntaxNode>(mask, 2);
                n.Expression = children.Node<SyntaxNode>(mask, 3);
                n.DefaultType = children.Node<SyntaxNode>(mask, 4);
                break;
            case ParameterDeclarationNode n:
                n.Modifiers = children.List(mask, 0);
                n.DotDotDotToken = children.Node<SyntaxNode>(mask, 1);
                n.Name = children.Node<SyntaxNode>(mask, 2);
                n.QuestionToken = children.Node<SyntaxNode>(mask, 3);
                n.Type = children.Node<SyntaxNode>(mask, 4);
                n.Initializer = children.Node<SyntaxNode>(mask, 5);
                break;
            case HeritageClauseNode n:
                n.Types = children.List(mask, 0);
                break;
            case ExpressionWithTypeArgumentsNode n:
                n.Expression = children.Node<SyntaxNode>(mask, 0);
                n.TypeArguments = children.List(mask, 1);
                break;
            case TypeReferenceNode n:
                n.TypeName = children.Node<SyntaxNode>(mask, 0);
                n.TypeArguments = children.List(mask, 1);
                break;
            case EnumMemberNode n:
                n.Name = children.Node<SyntaxNode>(mask, 0);
                n.Initializer = children.Node<SyntaxNode>(mask, 1);
                break;
            case ImportSpecifierNode n:
                n.PropertyName = children.Node<SyntaxNode>(mask, 0);
                n.Name = children.Node<IdentifierNode>(mask, 1);
                break;
            case ExportSpecifierNode n:
                n.PropertyName = children.Node<SyntaxNode>(mask, 0);
                n.Name = children.Node<SyntaxNode>(mask, 1);
                break;
            case TemplateSpanNode n:
                n.Expression = children.Node<SyntaxNode>(mask, 0);
                n.Literal = children.Node<SyntaxNode>(mask, 1);
                break;
            case ImportAttributeNode n:
                n.Name = children.Node<SyntaxNode>(mask, 0);
                n.Value = children.Node<SyntaxNode>(mask, 1);
                break;
            case TemplateLiteralTypeSpanNode n:
                n.Type = children.Node<SyntaxNode>(mask, 0);
                n.Literal = children.Node<SyntaxNode>(mask, 1);
                break;
            case JsxExpressionNode n:
                n.DotDotDotToken = children.Node<SyntaxNode>(mask, 0);
                n.Expression = children.Node<SyntaxNode>(mask, 1);
                break;
            case JsxElementNode n:
                n.OpeningElement = children.Node<JsxOpeningElementNode>(mask, 0);
                n.Children = children.List(mask, 1);
                n.ClosingElement = children.Node<JsxClosingElementNode>(mask, 2);
                break;
            case JsxSelfClosingElementNode n:
                n.TagName = children.Node<SyntaxNode>(mask, 0);
                n.TypeArguments = children.List(mask, 1);
                n.Attributes = children.Node<JsxAttributesNode>(mask, 2);
                break;
            case JsxFragmentNode n:
                n.OpeningFragment = children.Node<JsxOpeningFragmentNode>(mask, 0);
                n.Children = children.List(mask, 1);
                n.ClosingFragment = children.Node<JsxClosingFragmentNode>(mask, 2);
                break;
            case JsxAttributeNode n:
                n.Name = children.Node<SyntaxNode>(mask, 0);
                n.Initializer = children.Node<SyntaxNode>(mask, 1);
                break;
            case JsxSpreadAttributeNode n:
                n.Expression = children.Node<SyntaxNode>(mask, 0);
                break;
            case DecoratorNode n:
                n.Expression = children.Node<SyntaxNode>(mask, 0);
                break;
            case BlockNode n:
                n.Statements = children.List(mask, 0);
                break;
            case ModuleBlockNode n:
                n.Statements = children.List(mask, 0);
                break;
            case ModuleDeclarationNode n:
                n.Modifiers = children.List(mask, 0);
                n.Name = children.Node<SyntaxNode>(mask, 1);
                n.Attributes = children.Node<TypeLiteralNode>(mask, 2);
                n.Body = children.Node<SyntaxNode>(mask, 3);
                break;
            case ComputedPropertyNameNode n:
                n.Expression = children.Node<SyntaxNode>(mask, 0);
                break;
            case JSDocLinkNode n:
                n.Name = children.OptionalNode<SyntaxNode>();
                break;
            case JSDocLinkCodeNode n:
                n.Name = children.OptionalNode<SyntaxNode>();
                break;
            case JSDocLinkPlainNode n:
                n.Name = children.OptionalNode<SyntaxNode>();
                break;
            case QualifiedNameNode n:
                n.Left = children.Node<SyntaxNode>(mask, 0);
                n.Right = children.Node<SyntaxNode>(mask, 1);
                break;
            case IfStatementNode n:
