            case ImportClauseNode n:
                n.Name = children.Node<IdentifierNode>(mask, 0);
                n.NamedBindings = children.Node<SyntaxNode>(mask, 1);
                break;
            case SyntheticReferenceExpressionNode n:
                n.Expression = children.Node<SyntaxNode>(mask, 0);
                n.ThisArg = children.Node<SyntaxNode>(mask, 1);
                break;
            case JSDocTypeLiteralNode n:
                n.JSDocPropertyTags = children.Raw(mask, 0);
                break;
            case JSDocParameterOrPropertyTagNode n:
                n.TagName = children.Node<IdentifierNode>(mask, 0);
                n.Name = children.Node<SyntaxNode>(mask, 1);
                n.TypeExpression = children.Node<SyntaxNode>(mask, 2);
                n.Comment = children.List(mask, 3);
                break;
        }
    }

}
